package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;

/** Fictional initial operation receipt, exact native intent metadata; no input/body/send authority. */
class InitialReportActionsTest {
 InitialReportIntentTest h;JdbcReportInitialActions store;JdbcReportInitialActions.Command command;JdbcReportInitialActions.Accepted accepted;
 String key=JdbcReportInitialActions.action("fictional-initial-owner-key");Instant at=Instant.parse("2026-01-02T01:00:00.123456Z");
 boolean mysql(){return false;}
 @BeforeEach void setup(){h=new InitialReportIntentTest(){@Override GenerationJdbcStoreTest fixture(){return InitialReportActionsTest.this.mysql()?new GenerationJdbcStoreMySqlTest():new GenerationJdbcStoreTest();}};h.setup();var intent=h.ensure();store=new JdbcReportInitialActions(h.f.source);command=new JdbcReportInitialActions.Command(h.scope(),"fictional-owner","Fictional initial natural period");accepted=new JdbcReportInitialActions.Accepted(JdbcReportInitialActions.operation(key),intent,null,"free",0,null);}
 JdbcReportInitialActions.Accepted save(){return h.f.writes.execute(new SharedWriteExecutor.ActionContext(key,accepted.operationId(),null),k->store.read(k,command),a->{store.append(key,command,accepted,at);return store.read(key,command);});}
 @Test void ExactPermanentInitialReceiptReplaysBeforeLaterIntentStateAndNeverCreatesBudget(){assertNull(h.rr(()->store.read(key,command)));assertEquals(accepted,save());assertEquals(accepted,save());store=new JdbcReportInitialActions(h.f.source);h.f.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",accepted.intent().id());assertEquals(accepted,h.rr(()->store.read(key,command)));assertEquals(2L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));assertEquals(0L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind IN ('logical_task','ai_attempt','snapshot_part')",Long.class));assertTrue(accepted.toString().contains("redacted"));}
 @Test void SameKeyDifferentActorOrReasonConflictsAfterWholeOriginalValidation(){save();for(var other:List.of(new JdbcReportInitialActions.Command(command.scope(),"fictional-other",command.reason()),new JdbcReportInitialActions.Command(command.scope(),command.actor(),"Fictional different reason")))assertThrows(JdbcReportInitialActions.Conflict.class,()->h.rr(()->store.read(key,other)));h.f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE id=?",new byte[32],accepted.operationId());var error=assertThrows(RuntimeException.class,()->h.rr(()->store.read(key,new JdbcReportInitialActions.Command(command.scope(),command.actor(),"Fictional different reason"))));assertFalse(error instanceof JdbcReportInitialActions.Conflict);}
 @Test void CorruptReceiptRoleHashOrNativeTimeNeverReplays(){save();h.f.jdbc.update("UPDATE jobs SET reason='Fictional tampered reason' WHERE id=?",accepted.operationId());assertThrows(RuntimeException.class,()->h.rr(()->store.read(key,command)));setup();save();h.f.jdbc.update("UPDATE jobs SET record_identity_hash=? WHERE id=?",new byte[32],accepted.operationId());assertThrows(RuntimeException.class,()->h.rr(()->store.read(key,command)));setup();save();h.f.jdbc.update("UPDATE jobs SET updated_at=? WHERE id=?",java.sql.Timestamp.from(at.plusSeconds(1)),accepted.operationId());assertThrows(RuntimeException.class,()->h.rr(()->store.read(key,command)));}
 @Test void FailureAndForgedInitialSnapshotRollBackWithoutAnyNewReceipt(){h.f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_initial_receipt_failure CHECK(target_type IS NULL OR target_type<>'report_initial_request')");assertThrows(RuntimeException.class,this::save);assertNull(h.rr(()->store.read(key,command)));assertEquals(1L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));setup();var original=accepted.intent();accepted=new JdbcReportInitialActions.Accepted(accepted.operationId(),new JdbcInitialReportIntent.Initial(original.id(),original.scope(),1,1,original.state(),original.inputState(),original.coverage(),original.cutoff(),original.createdAt(),original.updatedAt()),null,"free",0,null);assertThrows(RuntimeException.class,this::save);assertNull(h.rr(()->store.read(key,command)));}
 @Test void ConcurrentSameKeyCommitsOneReceiptWithWholeSecondMicrosecondPrecision()throws Exception{at=Instant.parse("2026-01-02T01:00:00Z");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var one=pool.submit(this::save);var two=pool.submit(this::save);assertEquals(accepted,one.get(10,java.util.concurrent.TimeUnit.SECONDS));assertEquals(accepted,two.get(10,java.util.concurrent.TimeUnit.SECONDS));}assertEquals(2L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));assertEquals(command,h.rr(()->store.original(key)).command());}
 @Test void ColdConstructorAndWrongTransactionHeadersOrCoverageRefuse(){var source=mock(javax.sql.DataSource.class);new JdbcReportInitialActions(source);verifyNoInteractions(source);assertThrows(RuntimeException.class,()->store.read(key,command));assertThrows(RuntimeException.class,()->h.rr(()->{store.append(key,command,accepted,at);return true;}));assertThrows(RuntimeException.class,()->JdbcReportInitialActions.action("bad key"));var old=accepted;accepted=new JdbcReportInitialActions.Accepted(old.operationId(),old.intent(),"{\"state\":\"complete\",\"missing_inputs\":[],\"missing_dates\":[],\"no_update_dates\":[]}","free",0,null);assertThrows(RuntimeException.class,this::save);assertEquals(1L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));}
}
